import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { entryIdOf, entryListSha256, pick, rank, roundPublishedAt } from "./rank.js";

// Generated by test/fixtures/draw/rank-oracle.py: draw_group.py v3's own sort key, synthetic ids.
const vectors = JSON.parse(
  fs.readFileSync(path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../test/fixtures/draw/rank-vectors.json"), "utf8"),
) as Array<{ randomness: string; ids: string[]; ranked: string[]; winners: string[]; alternates: string[]; entry_list_sha256: string }>;

describe("rank", () => {
  it("reproduces the Python oracle on every synthetic vector", () => {
    expect(vectors).toHaveLength(3);
    for (const vector of vectors) {
      expect(rank(vector.randomness, vector.ids)).toEqual(vector.ranked);
      expect(pick(rank(vector.randomness, vector.ids))).toEqual({ winners: vector.winners, alternates: vector.alternates });
      expect(entryListSha256(vector.ids)).toBe(vector.entry_list_sha256);
    }
  });

  it("lets everyone win below ten entrants, with no alternates", () => {
    const small = vectors[0]!;
    expect(pick(rank(small.randomness, small.ids))).toEqual({ winners: small.ranked, alternates: [] });
  });

  it("refuses randomness that is not 32 bytes of hex, and maps hashes to entry ids", () => {
    expect(() => rank("abc", [])).toThrow(/32 bytes/);
    expect(entryIdOf("0123456789abcdef".repeat(4))).toBe("e_0123456789abcdef");
    expect(roundPublishedAt(33290248)).toBe(1692803367 + 33290247 * 3);
  });
});
